<script setup>
import { Head, Link } from '@inertiajs/vue3';
const props = defineProps({ organization: Object, currentBranch: Object, shift: Object, summary: Object, movements: Array });
function money(value) { return Number(value || 0).toLocaleString('ar-EG', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
function printReport() { window.print(); }
function varianceLabel(value) { const n = Number(value || 0); return n < 0 ? 'عجز' : n > 0 ? 'زيادة' : 'مطابق'; }
</script>

