        <section class="rounded-2xl border border-white/10 bg-slate-900 p-5 print:border-black print:bg-white"><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><div><p class="text-xs text-slate-400 print:text-gray-600">رقم الوردية</p><strong class="mt-1 block">#{{ shift.id }} · {{ shift.status === 'open' ? 'مفتوحة' : 'مغلقة' }}</strong></div><div><p class="text-xs text-slate-400 print:text-gray-600">الكاشير</p><strong class="mt-1 block">{{ shift.cashierName || '—' }}</strong></div><div><p class="text-xs text-slate-400 print:text-gray-600">وقت الفتح</p><strong class="mt-1 block">{{ shift.openedAt || '—' }}</strong></div><div><p class="text-xs text-slate-400 print:text-gray-600">وقت الإغلاق</p><strong class="mt-1 block">{{ shift.closedAt || 'لم تُغلق بعد' }}</strong></div></div></section>
