        <section class="overflow-x-auto rounded-2xl border border-white/10 bg-slate-900 p-5 print:border-gray-300 print:bg-white"><div class="flex flex-wrap items-center justify-between gap-2"><h2 class="text-lg font-black">سجل القبض والصرف</h2><span class="text-sm text-slate-400 print:text-gray-600">{{ summary.movementCount }} حركة</span></div><table class="mt-4 w-full min-w-[760px] text-right text-sm"><thead class="text-slate-400 print:text-gray-600"><tr><th class="p-3">التاريخ</th><th class="p-3">نوع الحركة</th><th class="p-3">المرجع</th><th class="p-3">المبلغ</th><th class="p-3">أثر النقدية</th><th class="p-3">المستخدم</th></tr></thead><tbody><tr v-for="movement in movements" :key="movement.id" class="border-t border-white/5 print:border-gray-200"><td class="p-3">{{ movement.date }}</td><td class="p-3">{{ movement.typeLabel }}</td><td class="p-3">{{ movement.reference || movement.notes || '—' }}</td><td class="p-3">{{ money(movement.amount) }} ج.م</td><td class="p-3">{{ money(movement.cashEffect) }} ج.م</td><td class="p-3">{{ movement.createdBy || '—' }}</td></tr><tr v-if="!movements.length"><td colspan="6" class="p-7 text-center text-slate-500">لا توجد حركات مسجلة في هذه الوردية.</td></tr></tbody></table></section>
